import{_ as a,o as e,c as n,a3 as i}from"./chunks/framework.CTwvqqO-.js";const p=JSON.parse('{"title":"スクラムバン運用ガイド","description":"スクラムバン(Scrumban)は、スクラムの反復的構造とカンバンのフロー管理・WIP制限を組み合わせ、柔軟かつ効率的に作業を管理するハイブリッドアジャイル方法論です。","frontmatter":{"title":"スクラムバン運用ガイド","description":"スクラムバン(Scrumban)は、スクラムの反復的構造とカンバンのフロー管理・WIP制限を組み合わせ、柔軟かつ効率的に作業を管理するハイブリッドアジャイル方法論です。","head":[["meta",{"name":"keywords","content":"スクラムバン, Scrumban, スクラムバン紹介, スクラムバンの概念, スクラムバンとは, Scrumban紹介, Scrumban概念, スクラムとカンバンの違い, スクラム vs カンバン, アジャイル方法論, アジャイルフレームワーク, カンバン方法論, スクラム方法論, スクラムバンプロセス, スクラムバン運用ガイド, スクラムバンボード, WIP制限, ワークフロー管理, カンバンボードの使い方, スクラムバンのメリット, スクラムバンの特徴, スクラムバンの効果, スクラムバン活用事例, スクラムバン導入効果, スクラムバン Jira設定, スクラムバンボードテンプレート, Scrumbanツール, スクラムバンコラボレーションツール, スクラムバンワークフロー, アジャイルプロジェクト管理, 業務効率化方法論, 反復的作業管理, ボトルネック解消"}],["meta",{"property":"og:title","content":"スクラムバン"}],["meta",{"property":"og:description","content":"スクラムバン(Scrumban)は、スクラムの反復的構造とカンバンのフロー管理・WIP制限を組み合わせ、柔軟かつ効率的に作業を管理するハイブリッドアジャイル方法論です。"}],["meta",{"property":"og:image","content":"https://empasy.io/docs/images/favicon.png"}],["meta",{"property":"og:url","content":"https://empasy.io/agile/guide.html"}],["link",{"rel":"canonical","href":"https://empasy.io/docs/ja/agile/guide.html"}]],"sort":300},"headers":[],"relativePath":"ja/agile/guide.md","filePath":"ja/agile/guide.md","lastUpdated":1788749177000}'),r={name:"ja/agile/guide.md"};function l(d,t,s,o,h,g){return e(),n("div",null,[...t[0]||(t[0]=[i(`<h1 id="📘-スクラムバン-scrumban-標準運用ガイド" tabindex="-1">📘 スクラムバン(Scrumban) 標準運用ガイド <a class="header-anchor" href="#📘-スクラムバン-scrumban-標準運用ガイド" aria-label="Permalink to “📘 スクラムバン(Scrumban) 標準運用ガイド”">​</a></h1><h2 id="_1-概要" tabindex="-1">1. 概要 <a class="header-anchor" href="#_1-概要" aria-label="Permalink to “1. 概要”">​</a></h2><p>スクラムバン(Scrumban)は、<strong>スクラム(Scrum)</strong> の構造と <strong>カンバン(Kanban)</strong> の柔軟なフロー管理方式を組み合わせたハイブリッドプロセスです。</p><ul><li><strong>スクラム</strong>が提供するルール・役割・バックログ管理</li><li><strong>カンバン</strong>が提供するWIP制限、プル(Pull)システム、フローの視覚化 この2つを組み合わせて、<strong>変化に素早く適応</strong>し、<strong>フローを最適化</strong>することが核心的な目的です。</li></ul><blockquote><p>🔑 <strong>核心哲学</strong> 「<strong>Stop starting, start finishing</strong>」 — 新しい作業を始めるよりも、進行中の仕事を終わらせよ。</p></blockquote><hr><h2 id="_2-基本原則" tabindex="-1">2. 基本原則 <a class="header-anchor" href="#_2-基本原則" aria-label="Permalink to “2. 基本原則”">​</a></h2><ol><li><strong>プル(Pull)ベースの作業</strong></li></ol><ul><li>作業はチームが処理可能な時にのみ開始します。</li><li>強制的に「押し込む」作業はフローを壊します。</li></ul><ol start="2"><li><strong>WIP(Work In Progress)制限</strong></li></ol><ul><li>同時に進行中の作業数を制限することで、品質低下やマルチタスクの問題を防ぎます。</li><li>例: チームメンバーが5人の場合、Doing WIP = 3。</li></ul><ol start="3"><li><strong>ワークフローの視覚化</strong></li></ol><ul><li>カンバンボードですべての作業状態を一目でわかるように表示します。</li><li>ボトルネックを即座に確認できます。</li></ul><ol start="4"><li><strong>明確なポリシー(Explicit Policies)</strong></li></ol><ul><li>各カラムへ移動できる条件(Definition of Ready / Doneなど)を文書化し、全チームメンバーで共有します。</li></ul><ol start="5"><li><strong>データに基づいた改善</strong></li></ol><ul><li>サイクルタイム・スループット・WIP・CFD(累積フロー図)などを測定し、改善の方向性を決定します。</li></ul><hr><h2 id="_3-役割と責任" tabindex="-1">3. 役割と責任 <a class="header-anchor" href="#_3-役割と責任" aria-label="Permalink to “3. 役割と責任”">​</a></h2><table tabindex="0"><thead><tr><th>役割</th><th>主な責任</th><th>備考</th></tr></thead><tbody><tr><td><strong>Product Owner (PO)</strong></td><td>バックログ管理、優先順位設定、要件の明確化、ビジネス目標の伝達</td><td>スクラムと同じまま維持</td></tr><tr><td><strong>Flow Manager / Scrum Master</strong></td><td>WIPモニタリング、ボトルネック解消支援、振り返りの進行、プロセス改善の促進</td><td>カンバンにおけるService Delivery Managerの概念と類似</td></tr><tr><td><strong>チームメンバー(Dev/QAなど)</strong></td><td>WIP遵守、プルベースの作業、カード状態の更新、品質の保証</td><td>自律性と責任が必須</td></tr><tr><td><strong>ステークホルダー</strong></td><td>フィードバックの提供、デモ/レビューへの参加</td><td>定期的な関与が必要</td></tr></tbody></table><hr><h2 id="_4-プロセス段階別アクティビティ" tabindex="-1">4. プロセス段階別アクティビティ <a class="header-anchor" href="#_4-プロセス段階別アクティビティ" aria-label="Permalink to “4. プロセス段階別アクティビティ”">​</a></h2><table tabindex="0"><thead><tr><th>段階</th><th>アクティビティ</th><th>詳細説明</th><th>ポリシー(例)</th></tr></thead><tbody><tr><td><strong>Backlog</strong></td><td>リクエスト/アイデア収集</td><td>顧客の要望、バグ、技術的負債、新機能など、すべての作業の出発点</td><td>すべてのカードに優先順位とClass of Serviceを指定</td></tr><tr><td><strong>Ready</strong></td><td>DoR確認、作業準備完了</td><td>要件の明確化、リソース確保、テスト条件定義</td><td>DoRチェックリスト通過時のみ移動</td></tr><tr><td><strong>Doing</strong></td><td>作業進行</td><td>WIP制限内でプル(Pull)した後に開発/実装</td><td>Doing WIP = 3</td></tr><tr><td><strong>Review</strong></td><td>コード/ドキュメントレビュー</td><td>品質、標準、セキュリティ、テストカバレッジの確認</td><td>レビュアーの承認後、Testingへ移動</td></tr><tr><td><strong>Testing</strong></td><td>品質検証</td><td>自動・手動テスト、欠陥の修正</td><td>QA完了時、Doneへ移動</td></tr><tr><td><strong>Done</strong></td><td>作業完了</td><td>DoDを満たし、文書化/デプロイ完了、サイクルタイム記録</td><td>完了タグの付与</td></tr></tbody></table><hr><h2 id="_5-定義-definition-基準" tabindex="-1">5. 定義(Definition)基準 <a class="header-anchor" href="#_5-定義-definition-基準" aria-label="Permalink to “5. 定義(Definition)基準”">​</a></h2><h3 id="_5-1-definition-of-ready-dor" tabindex="-1">5.1 Definition of Ready (DoR) <a class="header-anchor" href="#_5-1-definition-of-ready-dor" aria-label="Permalink to “5.1 Definition of Ready (DoR)”">​</a></h3><ul><li>要件が明確で文書化されている</li><li>必要なデザイン/リソースが確保されている</li><li>テスト条件が定義されている</li><li>予想される作業範囲・難易度が確認されている</li></ul><h3 id="_5-2-definition-of-done-dod" tabindex="-1">5.2 Definition of Done (DoD) <a class="header-anchor" href="#_5-2-definition-of-done-dod" aria-label="Permalink to “5.2 Definition of Done (DoD)”">​</a></h3><ul><li>コードのマージおよびビルド成功</li><li>自動・手動テスト通過</li><li>ドキュメント/リリースノート作成</li><li>デプロイ(または顧客への引き渡し)完了</li></ul><hr><h2 id="_6-会議-event-運用ガイド" tabindex="-1">6. 会議(Event)運用ガイド <a class="header-anchor" href="#_6-会議-event-運用ガイド" aria-label="Permalink to “6. 会議(Event)運用ガイド”">​</a></h2><table tabindex="0"><thead><tr><th>会議</th><th>目的</th><th>周期</th><th>時間</th><th>特徴</th></tr></thead><tbody><tr><td><strong>Daily Stand-up</strong></td><td>進捗状況、ボトルネックの共有</td><td>毎日</td><td>10~15分</td><td>カラムのフローを中心とした議論</td></tr><tr><td><strong>Replenishment</strong></td><td>Ready カラムの補充</td><td>週1回 or 限界値到達時</td><td>30分</td><td>優先順位の再調整</td></tr><tr><td><strong>Retrospective</strong></td><td>プロセスの改善</td><td>2~4週ごと</td><td>30~60分</td><td>WIP・ポリシーの調整</td></tr><tr><td><strong>Service Delivery Review</strong></td><td>SLA/SLEレビュー</td><td>月1回</td><td>30分</td><td>指標に基づいたレビュー</td></tr></tbody></table><hr><h2 id="_7-wip制限の運用" tabindex="-1">7. WIP制限の運用 <a class="header-anchor" href="#_7-wip制限の運用" aria-label="Permalink to “7. WIP制限の運用”">​</a></h2><ul><li><p>初期値: <code>チームメンバー数 ÷ 2</code></p></li><li><p>カラム別WIPの例:</p><ul><li>Doing: 3</li><li>Review: 2</li><li>Testing: 2</li></ul></li><li><p>WIP超過時は直ちに原因分析(ボトルネック、人員不足、ブロッカーなど)</p></li><li><p>解決するまで新規作業の開始を禁止</p></li></ul><hr><h2 id="_8-メトリクス管理" tabindex="-1">8. メトリクス管理 <a class="header-anchor" href="#_8-メトリクス管理" aria-label="Permalink to “8. メトリクス管理”">​</a></h2><table tabindex="0"><thead><tr><th>指標</th><th>定義</th><th>活用</th></tr></thead><tbody><tr><td><strong>リードタイム</strong></td><td>リクエスト発生 → 完了</td><td>顧客の待機時間の分析</td></tr><tr><td><strong>サイクルタイム</strong></td><td>作業開始 → 完了</td><td>フローの安定性の測定</td></tr><tr><td><strong>スループット</strong></td><td>一定期間に完了したカード数</td><td>生産性の予測</td></tr><tr><td><strong>平均WIP</strong></td><td>進行中の作業の平均</td><td>ボトルネック・マルチタスクの防止</td></tr><tr><td><strong>CFD</strong></td><td>カラム別の累積作業数</td><td>ボトルネック区間の把握</td></tr></tbody></table><blockquote><p><strong>Tip:</strong> リトルの法則 (Little’s Law) を活用する <code>WIP = Throughput × Cycle Time</code> → WIP・スループット・サイクルタイムのいずれかを調整すると、残りの要素が変化します。</p></blockquote><hr><h2 id="_9-運用ルールの例" tabindex="-1">9. 運用ルールの例 <a class="header-anchor" href="#_9-運用ルールの例" aria-label="Permalink to “9. 運用ルールの例”">​</a></h2><ol><li>プル(Pull)前に必ずWIPを確認</li><li>すべてのカードに優先順位・担当者を指定</li><li>ブロッカーを直ちに表示(ステッカー/ラベル)</li><li>会議時間は厳格に制限(Stand-up ≤ 15分)</li><li>プロセスの変更は振り返りで合意した後に反映</li></ol><hr><h2 id="_10-プロセスの視覚化例" tabindex="-1">10. プロセスの視覚化例 <a class="header-anchor" href="#_10-プロセスの視覚化例" aria-label="Permalink to “10. プロセスの視覚化例”">​</a></h2><div class="language-"><button title="Copy code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[Backlog]</span></span>
<span class="line"><span>  ↓ (Replenishment)</span></span>
<span class="line"><span>[Ready]</span></span>
<span class="line"><span>  ↓ (Pull &amp; WIP Check)</span></span>
<span class="line"><span>[Doing]</span></span>
<span class="line"><span>  ↓ (開発完了)</span></span>
<span class="line"><span>[Review]</span></span>
<span class="line"><span>  ↓ (レビュー承認)</span></span>
<span class="line"><span>[Testing]</span></span>
<span class="line"><span>  ↓ (品質検証完了)</span></span>
<span class="line"><span>[Done]</span></span></code></pre></div><hr><h2 id="_11-改善サイクル" tabindex="-1">11. 改善サイクル <a class="header-anchor" href="#_11-改善サイクル" aria-label="Permalink to “11. 改善サイクル”">​</a></h2><ol><li>メトリクスの収集 (サイクルタイム、スループット、WIP)</li><li>ボトルネックおよび変動性の分析</li><li>WIP制限・ポリシー・ボード構造の調整</li><li>1〜2週間のテスト適用</li><li>振り返りで効果を検証後、確定</li></ol><hr><h2 id="_12-付録" tabindex="-1">12. 付録 <a class="header-anchor" href="#_12-付録" aria-label="Permalink to “12. 付録”">​</a></h2><h3 id="classes-of-service-の例" tabindex="-1">Classes of Service の例 <a class="header-anchor" href="#classes-of-service-の例" aria-label="Permalink to “Classes of Service の例”">​</a></h3><ul><li><strong>Expedite</strong>: 直ちに処理(緊急)</li><li><strong>Fixed Date</strong>: 特定の日に締め切り</li><li><strong>Standard</strong>: 一般的なリクエスト</li><li><strong>Intangible</strong>: 技術的負債などの長期的な価値</li></ul><h3 id="推奨ツール" tabindex="-1">推奨ツール <a class="header-anchor" href="#推奨ツール" aria-label="Permalink to “推奨ツール”">​</a></h3><ul><li>Jira, Trello, Azure DevOps, Miro, ClickUp</li></ul><hr><p><strong>📌 核心メッセージ</strong> スクラムバンは「<strong>ルールを最小限に維持し、フローを最適化する</strong>」方法論です。 プロセスは、チームの<strong>データと合意</strong>に基づいて継続的に進化させる必要があります。</p><hr>`,57)])])}const b=a(r,[["render",l]]);export{p as __pageData,b as default};
